std::vector<int> seq_a = {1, 3, 5, 7, 9};
std::vector<int> seq_b = {1, 3, 6, 8, 9};

// Predicate: check if elements are equal
auto eq_check = [](int a, int b) { return a == b; };

// Use four-iterator overload with custom predicate
auto [it_a, it_b] = std::mismatch(seq_a.begin(), seq_a.end(),
                                  seq_b.begin(), seq_b.end(),
                                  eq_check);

// Calculate index of first mismatch
if (it_a != seq_a.end()) {
    ptrdiff_t mismatch_index = std::distance(seq_a.begin(), it_a);
}

// Result: mismatch_index == 2 (where 5 != 6)
